function transform(ctx) {
  // 昌吉学院：ac_id=2（AC 名 PA / paip 219.247.79.133）。换接入设备时改这里的 acId。
  const acId = '2';
  const n = '200';
  const type = '1';
  const ip = ctx.local_ip;
  if (!ip) throw new Error('无法读取本机 IPv4，请检查校园网接口');
  const token = ctx.vars.challenge;
  const info = srun_info(JSON.stringify({ username: ctx.username, password: ctx.password, ip: ip, acid: acId, enc_ver: 'srun_bx1' }), token);
  const hmd5 = hmac_md5(token, ctx.password);
  const checksum = sha1(token + ctx.username + token + hmd5 + token + acId + token + ip + token + n + token + type + token + info);
  return { encoded_username: url_encode(ctx.username), encoded_password: url_encode('{MD5}' + hmd5), encoded_info: url_encode(info), checksum: checksum, ac_id: acId, n: n, protocol_type: type };
}
